import{_ as t,c as a,o as d,ae as i}from"./chunks/framework.Ck3L_38O.js";const h=JSON.parse('{"title":"Steam 状态监控插件V2","description":"","frontmatter":{},"headers":[],"relativePath":"Steam状态监控.md","filePath":"Steam状态监控.md"}'),l={name:"Steam状态监控.md"};function o(c,e,m,r,s,n){return d(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="steam-状态监控插件v2" tabindex="-1">Steam 状态监控插件V2 <a class="header-anchor" href="#steam-状态监控插件v2" aria-label="Permalink to &quot;Steam 状态监控插件V2&quot;">​</a></h1><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li>支持定时轮询多个 SteamID 的状态，分群管理，每个群聊可独立配置监控玩家</li><li>检测玩家上线、下线、开始/切换/退出游戏等状态变更，自动推送游戏启动/关闭提醒</li><li>成就变动自动推送提醒</li><li>已配置自动轮询频率，默认为1-30分钟查询一次状态，取决于steam的上次在线时间，可以在后台修改</li><li>持久化记录玩家游玩日志，重启bot后状态不会丢失</li></ul><h2 id="默认轮询间隔说明" tabindex="-1">默认轮询间隔说明 <a class="header-anchor" href="#默认轮询间隔说明" aria-label="Permalink to &quot;默认轮询间隔说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>玩家最近在线时间</th><th>轮询间隔</th></tr></thead><tbody><tr><td>游戏中</td><td>1分钟</td></tr><tr><td>12分钟内</td><td>3分钟</td></tr><tr><td>12分钟~3小时</td><td>5分钟</td></tr><tr><td>3小时~24小时</td><td>10分钟</td></tr><tr><td>24~48小时</td><td>20分钟</td></tr><tr><td>超过48小时</td><td>30分钟</td></tr></tbody></table><h2 id="指令列表" tabindex="-1">指令列表 <a class="header-anchor" href="#指令列表" aria-label="Permalink to &quot;指令列表&quot;">​</a></h2><ul><li><code>/steam on</code> 启动本群Steam状态监控</li><li><code>/steam off</code> 停止本群Steam状态监控</li><li><code>/steam list</code> 列出本群所有玩家当前状态</li><li><code>/steam alllist</code> 列出所有群聊分组及玩家状态</li><li><code>/steam config</code> 查看当前插件配置</li><li><code>/steam set [参数] [值]</code> 设置配置参数（如 <code>/steam set poll_interval_sec 30</code>）</li><li><code>/steam addid [SteamID]</code> 添加SteamID到本群监控列表</li><li><code>/steam delid [SteamID]</code> 从本群监控列表删除SteamID</li><li><code>/steam push_group [SteamID]</code> 添加id到联动推送的副群（轮询一次通知多个群聊）</li><li><code>/steam delpush_group [SteamID]</code>删除id联动推送的副群</li><li><code>/steam openbox [SteamID]</code> 查看指定SteamID的全部详细信息</li><li><code>/steam rs</code> 清除所有状态并初始化</li><li><code>/steam achievement_on</code> 开启本群Steam成就推送</li><li><code>/steam achievement_off</code> 关闭本群Steam成就推送</li><li><code>/steam test_achievement_render [steamid] [gameid] [数量]</code> 测试成就图片渲染</li><li><code>/steam test_game_start_render [steamid] [gameid]</code> 测试开始游戏图片渲染</li><li><code>/steam清除缓存</code> 清除所有头像、封面图等图片缓存</li><li><code>/steam help</code> 显示所有指令帮助</li></ul>',7)])])}const S=t(l,[["render",o]]);export{h as __pageData,S as default};
